import {activeRole,scopeFor,localDate,recordByRef,sourcesValid} from './model.mjs';
export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
export const btn=(action,label,extra='',cls='small-button')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
export const field=(name,label,value='',type='text',extra='')=>`<label class="field-label" for="f-${name}">${label}</label><input class="text-field" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
export const area=(name,label,value='',extra='')=>`<label class="field-label" for="f-${name}">${label}</label><textarea class="text-field" id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea>`;
export const select=(name,label,options,value)=>`<label class="field-label" for="f-${name}">${label}</label><select class="text-field" id="f-${name}" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
export const submit=label=>`<div class="sheet-actions"><button class="primary" type="submit">${label}</button></div>`;
export const empty=text=>`<p class="empty">${text}</p>`;
export const meta=text=>`<span class="meta">${esc(text)}</span>`;
export const liveRoles=state=>state.roles.filter(r=>!r.deleted);
export const roleName=(state,roleId)=>roleId==='user'?state.user.name:(state.roles.find(r=>r.id===roleId)?.name||'已移除角色');
export const avatar=(state,roleId,cls='avatar')=>`<img class="${cls}" data-media="${esc(state.roles.find(r=>r.id===roleId)?.avatar||'builtin-flowers')}" alt="${esc(roleName(state,roleId))}的头像">`;
export const checks=(state,name,selected=[],allowed=liveRoles(state))=>`<div class="check-list">${allowed.map(r=>`<label class="check-row"><input type="checkbox" name="${name}" value="${r.id}" ${selected.includes(r.id)?'checked':''}>${esc(r.name)}</label>`).join('')}</div>`;
const dateTime=value=>new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
export function tasksHTML(scope,targetId=null){
  return scope.tasks.filter(t=>(!targetId||t.targetId===targetId)&&t.status!=='done').slice(-12).map(t=>`<div class="task-line"><span>${esc(t.authorName||'角色')} · ${{waiting:'等待回复',running:'正在生成',failed:'生成失败',cancelled:'已停止'}[t.status]}</span>${t.error?meta(t.error):''}<div class="toolbar">${['failed','cancelled'].includes(t.status)?btn('retry-task','重试',`data-id="${t.id}"`):btn('cancel-task','停止',`data-id="${t.id}"`)}</div></div>`).join('');
}
const searchForm=(route,label='搜索关键词')=>`<form id="search-form"><div class="toolbar"><input class="text-field" name="query" aria-label="${label}" placeholder="${label}" value="${esc(route.query||'')}"><button class="secondary">搜索</button>${btn('favorites-filter',route.favorites?'查看全部':'只看收藏')}</div></form>`;
function matches(text,query){return !query||text.toLocaleLowerCase().includes(query.toLocaleLowerCase());}
function mediaHTML(ids){return (ids||[]).map(mid=>`<img class="post-image" data-media="${esc(mid)}" alt="附图">`).join('');}
function favorite(scope,type,id){return scope.favorites.some(f=>f.type===type&&f.id===id);}
function entryActions(scope,type,record){return `<div class="toolbar">${btn('favorite',favorite(scope,type,record.id)?'已收藏':'收藏',`data-kind="${type}" data-id="${record.id}" aria-pressed="${favorite(scope,type,record.id)}"`)}${btn('edit-record','编辑',`data-kind="${type}" data-id="${record.id}"`)}${(record.sourceRefs||[]).length?btn('view-sources','查看来源',`data-kind="${type}" data-id="${record.id}"`):''}${btn('delete-record','移入回收站',`data-kind="${type}" data-id="${record.id}"`)}</div>`;}

export function renderPanel(state,route){
  const role=activeRole(state),scope=scopeFor(state,route.key)||scopeFor(state),world=state.worlds.find(w=>w.id===scope?.worldId),roles=liveRoles(state);
  const common={kicker:role?`${role.name}的小手机 · ${world?.name||'日常'}`:'轻玻璃小手机'};
  let title='',html='';
  switch(route.name){
  case 'sources':{
    const record=recordByRef(scope,{type:route.kind,id:route.id});title='内容来源';html=(record.sourceRefs?.length?record.sourceRefs:record.originalSources||[]).map(ref=>{const original=recordByRef(scope,ref);return `<div class="card"><p class="prose">${esc(original&&!original.deleted?(original.text||original.title):'原内容已移除')}</p>${original&&!original.deleted?btn('open-source','打开原文',`data-kind="${ref.type}" data-id="${ref.id}"`):''}</div>`;}).join('')||empty('这是一条手工记录。');break;}
  case 'chats':
    title='消息';html=`<div class="toolbar">${btn('home','回到桌面')}${btn('new-chat','新私聊')}${btn('new-group','建群')}</div>${(scope?.chats||[]).map(c=>{const last=c.messages.filter(m=>!m.deleted).at(-1),unread=c.messages.filter(m=>!m.deleted&&m.authorId!=='user'&&m.at>c.readAt).length;return `<button class="list-row" data-action="open-chat" data-id="${c.id}">${avatar(state,c.members[0])}<span><strong>${esc(c.kind==='private'?roleName(state,c.members[0]):c.name)}</strong><small>${esc(last?.text?.slice(0,60)||'点这里开始聊天')}</small></span>${unread?`<b class="badge">${unread}</b>`:''}</button>`;}).join('')||empty('添加一个角色，开始聊天吧。')}`;break;
  case 'new-chat':case 'new-group':{
    const group=route.name==='new-group';title=group?'一起聊聊':'选择聊天角色';html=`<form id="new-chat-form">${group?field('name','群聊名字','新的群聊'):''}<p class="hint">${group?'选择至少两位角色，每条回复会标明发言者。':'选择一位角色进入私聊。'}</p>${group?checks(state,'members',roles.map(r=>r.id)):select('member','聊天对象',roles.map(r=>[r.id,r.name]),role?.id)}${submit(group?'创建群聊':'开始聊天')}</form>`;break;}
  case 'chat-options':{
    const chat=scope.chats.find(c=>c.id===route.id);title='会话设置';html=`<form id="chat-settings-form">${field('name','会话名字',chat.name,'text','required')}${chat.kind==='group'?`<span class="field-label">群成员</span>${checks(state,'members',chat.members)}`:''}${submit('保存会话设置')}</form><div class="toolbar">${btn('respond','选择回复者')}${btn('chat-search','搜索与收藏')}${btn('tasks','生成记录')}</div>`;break;}
  case 'respond':{
    const chat=scope.chats.find(c=>c.id===route.id);title='这次由谁回复';html=`<form id="respond-form">${checks(state,'members',chat.members,roles.filter(r=>chat.members.includes(r.id)))}<p class="hint">按选择顺序分别回复，失败者可以单独重试。</p>${submit('让角色回复')}</form>${tasksHTML(scope,chat.id)}`;break;}
  case 'chat-search':{
    const chat=scope.chats.find(c=>c.id===route.id);title='查找聊天';html=searchForm(route,'搜索关键词、名字或日期')+chat.messages.filter(m=>!m.deleted&&matches(`${m.text} ${m.authorName} ${localDate(new Date(m.at))}`,route.query)&&(!route.favorites||favorite(scope,'message',m.id))).map(m=>`<button class="list-row" data-action="jump-message" data-id="${m.id}"><span><strong>${esc(m.authorName)} · ${localDate(new Date(m.at))}</strong><small>${esc(m.text||'附件')}</small></span></button>`).join('');break;}
  case 'message-actions':{
    const m=recordByRef(scope,{type:'message',id:route.id});title=m.authorName;html=`<p class="prose">${esc(m.text)}</p><div class="toolbar">${btn('favorite',favorite(scope,'message',m.id)?'取消收藏':'收藏消息',`data-kind="message" data-id="${m.id}"`)}${btn('quote-message','引用回复',`data-id="${m.id}"`)}${btn('memory-from-message','存为回忆',`data-id="${m.id}"`)}${btn('event-from-message','存为约定',`data-id="${m.id}"`)}${btn('speak-message','朗读并保存音频',`data-id="${m.id}"`)}${btn('edit-record','编辑消息',`data-kind="message" data-id="${m.id}"`)}${btn('delete-record','移入回收站',`data-kind="message" data-id="${m.id}"`)}</div>`;break;}
  case 'roles':
    title='角色';html=`<div class="toolbar">${btn('new-role','添加角色')}${btn('import-role','导入 JSON')}${btn('role-trash','已移除角色')}</div>${roles.map(r=>`<div class="card"><div class="card-head">${avatar(state,r.id)}<div><strong>${esc(r.name)}</strong>${meta(state.worlds.find(w=>w.id===r.worldId)?.name||'日常')}</div>${r.id===state.activeId?'<span class="badge">当前</span>':''}</div><div class="toolbar">${btn('switch-role','进入这部手机',`data-id="${r.id}"`)}${btn('edit-role','角色设置',`data-id="${r.id}"`)}${btn('memories','共同回忆',`data-owner="${r.id}"`)}</div></div>`).join('')||empty('还没有角色，先添加一位吧。')}`;break;
  case 'role-form':{
    const r=route.values||state.roles.find(r=>r.id===route.id)||{name:'',persona:'',relation:'',metOn:localDate(),worldId:'daily',worldEnabled:true,avatar:'builtin-flowers'};
    title=route.id?'角色设置':route.imported?'导入角色预览':'添加角色';
    html=`${route.imported?'<p class="hint">已读取 JSON 的姓名、人设与关系。确认后创建新角色，原文件保留。</p>':''}<form id="role-form">${field('name','名字',r.name,'text','required maxlength="40"')}${area('persona','人设与说话习惯',r.persona,'maxlength="20000"')}${area('relation','与你的关系',r.relation,'maxlength="4000"')}${select('avatar','头像',state.media.filter(m=>m.type.startsWith('image/')).map(m=>[m.id,m.name]),r.avatar)}${field('metOn','相遇日期',r.metOn,'date','required')}${select('worldId','世界背景',state.worlds.map(w=>[w.id,w.name]),r.worldId)}<label class="switch-row"><span>启用世界背景</span><input class="switch" name="worldEnabled" type="checkbox" ${r.worldEnabled?'checked':''}></label>${submit(route.id?'保存角色':'添加并进入手机')}</form>${route.id?`<div class="toolbar">${btn('proactive','主动来信设置',`data-id="${r.id}"`)}${btn('delete-role','移除角色',`data-id="${r.id}"`,'small-button danger')}</div>`:''}`;break;}
  case 'role-trash':
    title='已移除角色';html=state.roles.filter(r=>r.deleted).map(r=>`<div class="card"><strong>${esc(r.name)}</strong>${meta('聊天和署名保留，恢复后可继续使用。')}${btn('restore-role','恢复角色',`data-id="${r.id}"`)}</div>`).join('')||empty('这里还没有移除的角色。');break;
  case 'worlds':
    title='世界背景';html=`<p class="hint">背景决定人物生活的世界；手机壁纸在外观里设置。</p>${btn('new-world','新建世界')}${state.worlds.map(w=>`<button class="list-row" data-action="edit-world" data-id="${w.id}"><span><strong>${esc(w.name)}</strong><small>${esc(w.body?.slice(0,65)||'还没有填写背景')}</small></span></button>`).join('')}`;break;
  case 'world-form':{
    const w=state.worlds.find(w=>w.id===route.id)||{name:'',body:'',timeMode:'real',date:localDate()};title=route.id?'编辑世界':'新建世界';html=`<form id="world-form">${field('name','世界名字',w.name,'text','required maxlength="60"')}${area('body','时代、地点、规则与共同背景',w.body,'maxlength="24000"')}${select('timeMode','日历时间',[['real','现实日期'],['story','故事日期']],w.timeMode)}${field('date','故事日期',w.date,'date','required')}${submit('保存世界')}</form>`;break;}
  case 'memories':
    title='共同回忆';html=`<div class="toolbar">${btn('new-memory','手写回忆')}${btn('generate-memory','整理角色经历')}</div>${scope.memories.filter(m=>!m.deleted).map(m=>`<div class="card"><p class="prose">${esc(m.text)}</p>${meta(m.participants.map(cid=>roleName(state,cid)).join('、'))}${meta(m.stale||!sourcesValid(scope,m)?'来源已变化，请检查后更新':m.manual?'手工记录':`来自 ${m.sourceRefs.length} 条经历`)}<div class="toolbar">${btn('toggle-memory',m.enabled?'已启用':'已停用',`data-id="${m.id}" aria-pressed="${m.enabled}"`)}${btn('pin-memory',m.pinned?'已固定':'固定',`data-id="${m.id}"`)}${btn('view-sources','查看来源',`data-kind="memory" data-id="${m.id}"`)}${btn('edit-record','编辑',`data-kind="memory" data-id="${m.id}"`)}${btn('delete-record','移入回收站',`data-kind="memory" data-id="${m.id}"`)}</div></div>`).join('')||empty('重要的话和一起经历的事，可以留在这里。')}${tasksHTML(scope)}`;break;
  case 'memory-form':{
    const m=scope.memories.find(m=>m.id===route.id)||{text:route.text||'',participants:[role.id],enabled:true,pinned:false};title=route.id?'编辑回忆':'留下一段回忆';html=`<form id="memory-form">${area('text','想记住的事',m.text,'required maxlength="12000"')}<span class="field-label">哪些角色知道这件事</span>${checks(state,'participants',m.participants,route.allowed?roles.filter(r=>route.allowed.includes(r.id)):roles)}<label class="check-row"><input name="enabled" type="checkbox" ${m.enabled?'checked':''}>在后续回复中使用</label><label class="check-row"><input name="pinned" type="checkbox" ${m.pinned?'checked':''}>固定这段回忆</label>${submit('保存回忆')}</form>`;break;}
  case 'calendar':
    title='约定与纪念日';html=`${meta(world?.timeMode==='story'?`故事日期 · ${world.date}`:'现实日历')}<div class="toolbar">${btn('new-event','添加约定')}${btn('diary','回到日记')}</div>${scope.events.filter(e=>!e.deleted).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="calendar-item"><strong>${esc(e.title)}</strong>${meta(`${e.date} ${e.time||''}${e.repeat==='yearly'?' · 每年':''} · ${{planned:'待赴约',done:'已完成',cancelled:'已取消'}[e.status]}`)}${meta(e.participants.map(cid=>roleName(state,cid)).join('、'))}<div class="toolbar">${btn('edit-record','编辑',`data-kind="event" data-id="${e.id}"`)}${e.status==='planned'?btn('complete-event','记录已完成',`data-id="${e.id}"`):''}${e.status!=='cancelled'?btn('cancel-event','取消约定',`data-id="${e.id}"`):''}</div></div>`).join('')||empty('从聊天留下一个约定，或记住一个特别的日子。')}`;break;
  case 'event-form':{
    const e=scope.events.find(e=>e.id===route.id)||{title:route.text||'',date:world?.timeMode==='story'?world.date:localDate(),time:'',repeat:'none',participants:[role.id],note:''};title=route.id?'编辑约定':'添加约定';html=`<form id="event-form">${field('title','约定或纪念日',e.title,'text','required maxlength="120"')}<div class="two-fields">${field('date','日期',e.date,'date','required')}${field('time','时间（可选）',e.time,'time')}</div>${select('repeat','重复',[['none','仅这一次'],['yearly','每年纪念']],e.repeat)}<span class="field-label">参与角色</span>${checks(state,'participants',e.participants)}${area('note','备注',e.note)}${submit('确认并保存约定')}</form>`;break;}
  case 'diary':
    title='日记';html=`<div class="toolbar">${btn('new-diary','自己写')}${btn('generate-diary','角色写日记')}${btn('calendar','约定与纪念日')}</div>${searchForm(route,'搜索正文、作者或日期')}${scope.diaries.filter(d=>!d.deleted&&matches(`${d.title} ${d.text} ${d.authorName} ${d.date}`,route.query)&&(!route.favorites||favorite(scope,'diary',d.id))).sort((a,b)=>b.date.localeCompare(a.date)||b.at-a.at).map(d=>`<article class="card" id="record-${d.id}"><div class="card-head">${d.authorId==='user'?'':avatar(state,d.authorId)}<div><strong>${esc(d.title)}</strong>${meta(`${d.authorName} · ${d.date}${d.status==='draft'?' · 草稿':''}`)}</div></div><p class="prose">${esc(d.text)}</p>${d.stale?meta('原经历已变化，可重新整理或自行修订。'):''}${entryActions(scope,'diary',d)}</article>`).join('')}${tasksHTML(scope)}`;break;
  case 'diary-form':{
    const d=scope.diaries.find(d=>d.id===route.id)||{title:'',text:'',date:world?.timeMode==='story'?world.date:localDate(),authorId:'user'};title=route.id?'编辑日记':'写下今天';html=`<form id="diary-form">${field('title','标题',d.title,'text','maxlength="120"')}${field('date','日期',d.date,'date','required')}${area('text','日记正文',d.text,'required maxlength="30000"')}${submit('保存日记')}</form>`;break;}
  case 'generate-diary':
    title='让角色写日记';html=`<form id="generate-diary-form">${select('authorId','日记作者',roles.map(r=>[r.id,r.name]),role.id)}${field('date','记录哪一天',world?.timeMode==='story'?world.date:localDate(),'date','required')}<p class="hint">从作者当天知道的聊天、动态和已完成约定整理，生成后保存为可编辑草稿。</p>${submit('生成日记')}</form>`;break;
  case 'moments':
    title='朋友圈';html=`<div class="toolbar">${btn('new-post','发动态')}${btn('generate-post','角色发动态')}</div>${searchForm(route,'搜索动态、作者或日期')}${scope.posts.filter(p=>!p.deleted&&matches(`${p.text} ${p.authorName} ${localDate(new Date(p.at))}`,route.query)&&(!route.favorites||favorite(scope,'post',p.id))).slice().reverse().map(p=>`<article class="card" id="record-${p.id}"><div class="card-head">${p.authorId==='user'?'':avatar(state,p.authorId)}<div><strong>${esc(p.authorName)}</strong>${meta(dateTime(p.at))}</div></div><p class="prose">${esc(p.text)}</p>${mediaHTML(p.media)}${meta('可见：'+p.audience.map(cid=>roleName(state,cid)).join('、'))}<div class="toolbar">${btn('like-post',`${p.likes.includes('user')?'已赞':'赞'} ${p.likes.length||''}`,`data-id="${p.id}"`)}${btn('comment-post','评论',`data-id="${p.id}"`)}${btn('role-comments','让角色回复',`data-id="${p.id}"`)}</div>${entryActions(scope,'post',p)}<div class="comments">${p.comments.filter(c=>!c.deleted).map(c=>`<div class="comment"><strong>${esc(c.authorName)}</strong>${c.replyTo?`<span class="reply-target"> 回复 ${esc(p.comments.find(x=>x.id===c.replyTo)?.authorName||'原评论')}</span>`:''}<p class="prose">${esc(c.text)}</p>${btn('reply-comment','回复',`data-post="${p.id}" data-id="${c.id}"`)}${btn('role-comments','角色接话',`data-id="${p.id}" data-reply="${c.id}"`)}</div>`).join('')}</div>${tasksHTML(scope,p.id)}</article>`).join('')||empty('分享一张照片，或今天想说的一句话。')}`;break;
  case 'post-form':{
    const p=scope.posts.find(p=>p.id===route.id)||{text:'',audience:roles.map(r=>r.id),media:[]};title=route.id?'编辑动态':'发一条动态';html=`<form id="post-form">${area('text','想分享什么',p.text,'maxlength="6000"')}<span class="field-label">配图（可多选）</span><div class="media-grid">${state.media.filter(m=>m.type.startsWith('image/')).map(m=>`<label class="check-row"><input type="checkbox" name="media" value="${m.id}" ${p.media.includes(m.id)?'checked':''}><span>${esc(m.name)}</span></label>`).join('')}</div><span class="field-label">谁能看到和回复</span>${checks(state,'audience',p.audience)}${submit('发布动态')}</form>`;break;}
  case 'comment-form':
    title=route.replyTo?'回复评论':'评论动态';html=`<form id="comment-form">${area('text','评论内容','','required maxlength="4000"')}${submit('发送评论')}</form>`;break;
  case 'role-comments':
    title='邀请角色回复';html=`<form id="role-comments-form">${checks(state,'members',scope.posts.find(p=>p.id===route.id).audience,roles.filter(r=>scope.posts.find(p=>p.id===route.id).audience.includes(r.id)))}${submit('分别回复')}</form>`;break;
  case 'generate-post':case 'generate-memory':
    title=route.name==='generate-post'?'角色发动态':'整理共同回忆';html=`<form id="generate-role-form">${select('authorId','选择角色',roles.map(r=>[r.id,r.name]),role.id)}${route.name==='generate-post'?`<span class="field-label">动态可见角色</span>${checks(state,'audience',roles.map(r=>r.id))}`:'<p class="hint">整理该角色已知的经历，保存后可以编辑、固定或停用。</p>'}${submit('开始生成')}</form>`;break;
  case 'edit-message':
    title='编辑消息';html=`<form id="edit-message-form">${area('text','消息正文',recordByRef(scope,{type:'message',id:route.id}).text,'required')}${submit('保存修改')}</form>`;break;
  default:return renderOther(state,route,common);
  }
  return {...common,title,html};
}

function renderOther(state,route,common){
  const role=activeRole(state),scope=scopeFor(state,route.key)||scopeFor(state);let title='',html='';
  switch(route.name){
  case 'settings':
    title='设置';html=`${[['api','API 与模型'],['voice-settings','语音服务'],['worlds','世界背景'],['appearance','壁纸与外观'],['identity','我的资料'],['data','备份、恢复与回收站'],['tasks','生成记录']].map(([action,label])=>`<button class="setting-link" data-action="${action}"><span>${label}</span>${icon('arrow')}</button>`).join('')}${role?`<button class="setting-link" data-action="proactive" data-id="${role.id}"><span>主动来信</span>${icon('arrow')}</button>`:''}${meta('内容保存在这个浏览器中；生成时使用你配置的服务。')}`;break;
  case 'api':{
    const c=route.values||state.connections.text;title='API 与模型';html=`<div class="toolbar">${btn('import-api','导入连接 JSON')}</div><p class="hint">支持兼容 Chat Completions 的服务。填写到接口根路径，例如 https://你的服务/v1。</p><form id="api-form">${field('baseUrl','服务地址',c.baseUrl,'url','required autocomplete="off"')}${field('secret','API 密钥（留空保留已存密钥）',route.values?.secret||'','password','autocomplete="new-password"')}${field('model','模型名称',c.model,'text','required list="api-models"')}<datalist id="api-models"></datalist><div class="toolbar">${btn('models','获取模型列表')}${btn('test-api','测试当前填写的连接')}</div><p class="task-status" id="api-status" role="status"></p><details><summary>回复参数</summary>${field('temperature','温度',c.temperature??.8,'number','min="0" max="2" step="0.1"')}${field('maxTokens','最多回复 Token',c.maxTokens||900,'number','min="64" max="8000"')}</details>${submit('保存连接')}</form>${btn('clear-key','清除已保存的密钥','data-kind="text"')}<p class="hint">密钥保存在本机服务设置中，备份会自动排除。</p>`;break;}
  case 'voice-settings':
    title='语音服务';html=`<p class="hint">语音识别和角色朗读分别接入兼容接口，可以使用不同服务。</p><form id="voice-form">${['transcription','speech'].map(kind=>{const c=state.connections[kind];return `<details ${kind==='speech'?'open':''}><summary>${kind==='speech'?'角色朗读':'录音识别'}</summary>${field(kind+'Url','服务地址',c.baseUrl,'url')}${field(kind+'Key','密钥（留空保留）','','password','autocomplete="new-password"')}${field(kind+'Model','模型',c.model)}${kind==='speech'?field('speechVoice','声音名称',c.voice):''}${btn('clear-key','清除这个密钥',`data-kind="${kind}"`)}</details>`;}).join('')}${submit('保存语音设置')}</form>`;break;
  case 'identity':
    title='我的资料';html=`<form id="identity-form">${field('name','你的称呼',state.user.name,'text','required maxlength="40"')}${area('description','想让角色知道的自己',state.user.description,'maxlength="4000"')}${submit('保存资料')}</form>`;break;
  case 'appearance':{
    const a=role.appearance;title='壁纸与外观';html=`<form id="appearance-form">${select('theme','主题',[['light','日光'],['dark','夜色']],a.theme)}<label class="switch-row"><span>轻玻璃效果</span><input class="switch" name="blur" type="checkbox" ${a.blur?'checked':''}></label>${select('wallpaper','手机壁纸',state.media.filter(m=>m.type.startsWith('image/')).map(m=>[m.id,m.name]),a.wallpaper)}${select('chatBackground','聊天背景',[['','跟随手机壁纸'],...state.media.filter(m=>m.type.startsWith('image/')).map(m=>[m.id,m.name])],a.chatBackground)}${select('fontScale','阅读字号',[[1,'标准 · 100%'],[1.5,'大字 · 150%'],[2,'特大 · 200%']],a.fontScale)}<label class="switch-row"><span>桌面音乐组件</span><input class="switch" name="music" type="checkbox" ${a.music?'checked':''}></label><div class="sheet-actions">${btn('preview-appearance','预览','','secondary')}<button class="primary">保存外观</button></div></form><p class="hint">这部手机单独保存外观。关闭面板会取消未保存的预览。</p>`;break;}
  case 'proactive':{
    const r=state.roles.find(r=>r.id===route.id),p=r.proactive;title=r.name+'的主动来信';html=`<form id="proactive-form"><label class="switch-row"><span>允许角色主动来信</span><input class="switch" name="enabled" type="checkbox" ${p.enabled?'checked':''}></label>${field('interval','最短间隔（分钟）',p.interval,'number','min="5" max="10080" required')}${field('dailyLimit','每日最多几次',p.dailyLimit,'number','min="1" max="20" required')}<div class="two-fields">${field('quietStart','安静时段开始（小时）',p.quietStart,'number','min="0" max="23" required')}${field('quietEnd','安静时段结束（小时）',p.quietEnd,'number','min="0" max="23" required')}</div><p class="hint">应用打开时按频率检查，优先联系当天的约定或纪念日。生成会使用当前 API；关闭页面后暂停，也不会补发积压问候。</p>${submit('保存来信规则')}</form>`;break;}
  case 'album':case 'attachments':{
    const attachments=route.name==='attachments';title=attachments?'选一张图片或表情':'相册';html=`<div class="toolbar">${btn('upload-images','添加图片')}${btn('album-filter',route.category==='表情'?'全部图片':'只看表情')}</div><div class="media-grid">${state.media.filter(m=>m.type.startsWith('image/')&&(!route.category||m.category===route.category)).map(m=>`<button data-action="${attachments?'attach-image':'media-detail'}" data-id="${m.id}"><img data-media="${m.id}" alt="${esc(m.name)}"><span>${esc(m.name)}</span></button>`).join('')}</div>`;break;}
  case 'media-detail':{
    const m=state.media.find(m=>m.id===route.id);title=m.name;html=`<img class="media-view" data-media="${m.id}" alt="${esc(m.name)}"><div class="toolbar">${btn('media-wallpaper','设为壁纸',`data-id="${m.id}"`)}${btn('media-avatar','设为头像',`data-id="${m.id}"`)}${btn('media-sticker',m.category==='表情'?'移出表情':'收为表情',`data-id="${m.id}"`)}${btn('open-original','查看原图',`data-id="${m.id}"`)}</div>${field('mediaName','图片名称',m.name)}${btn('rename-media','保存名称',`data-id="${m.id}"`)}`;break;}
  case 'music':{
    const track=state.media.find(m=>m.id===scope.playback.trackId)||state.media.find(m=>m.id==='builtin-music');const listening=scope.listening.find(l=>!l.endedAt);
    title='音乐与一起听';html=`<img class="big-cover" src="assets/portrait-birds.png" alt="飞鸟插画封面"><h3 class="player-title">${esc(track.name)}</h3><p class="player-subtitle">${listening?'正在与 '+listening.participants.map(cid=>roleName(state,cid)).join('、')+' 一起听':'选一首歌，留一会儿时间'}</p><label class="sr-only" for="seek">播放进度</label><input class="player-range" id="seek" type="range" min="0" max="100" step=".1"><div class="player-times"><span data-elapsed>0:00</span><span data-duration>0:24</span></div><div class="player-buttons">${btn('previous-track',icon('back'),'aria-label="上一首"','icon-button')}${btn('play',icon('play'),'aria-label="播放音乐"','play-button')}${btn('next-track',icon('arrow'),'aria-label="下一首"','icon-button')}</div><label class="volume-row">音量<input id="volume" type="range" min="0" max="1" step=".05" value="${scope.playback.volume}"></label><div class="toolbar">${btn('upload-music','添加音乐')}${btn('listen-together',listening?'结束一起听':'邀请角色一起听')}${btn('share-song','分享到聊天')}${listening?btn('choose-song','让角色选歌'):''}</div>${scope.playlist.map(mid=>{const m=state.media.find(m=>m.id===mid);return `<button class="list-row" data-action="select-track" data-id="${mid}"><span>${esc(m?.name||'曲目缺失')}</span>${mid===track.id?'<span class="badge">当前</span>':''}</button>`;}).join('')}<details><summary>一起听记录</summary>${scope.listening.slice().reverse().map(l=>`<div class="listen-history">${esc(l.participants.map(cid=>roleName(state,cid)).join('、'))} · ${dateTime(l.at)} · ${Math.floor((l.seconds||0)/60)} 分 ${(Math.floor(l.seconds||0)%60)} 秒${l.endedAt?'':' · 进行中'}${meta(l.tracks.map(mid=>state.media.find(m=>m.id===mid)?.name||'歌曲').join(' / '))}</div>`).join('')||empty('开始一起听后，实际播放时间会记在这里。')}</details>`;break;}
  case 'listen-form':
    title='邀请一起听';html=`<form id="listen-form">${checks(state,'members',[role.id])}${submit('开始一起听')}</form>`;break;
  case 'record':
    title='录一段声音';html=`<p class="hint">录音最多 60 秒。录好后可先试听、转成文字或补充文字，再发送。</p><div id="recorder-content"><div class="toolbar">${btn('start-recording','开始录音','','primary')}${btn('upload-voice','上传已有录音','','secondary')}</div></div><p id="record-status" class="task-status" role="status"></p>`;break;
  case 'data':
    title='备份与恢复';html=`<p class="hint">备份包含所有手机、世界、记录和原始附件，自动排除服务密钥。</p><div class="stack">${btn('export','导出完整备份','','primary')}${btn('import-backup','导入备份并预览','','secondary')}${btn('restore-points','恢复点','','secondary')}${btn('trash','内容回收站','','secondary')}</div>`;break;
  case 'backup-preview':
    title='恢复备份预览';html=`<p class="hint">备份中的内容将替换当前内容。恢复前会自动留下当前完整记录的恢复点。服务密钥需要重新填写。</p><div class="card">${meta(`角色 ${route.summary.roles} 位 · 手机世界空间 ${route.summary.scopes} 个 · 附件 ${route.summary.media} 个`)}</div>${btn('apply-backup','恢复这份备份','','primary')}`;break;
  case 'restore-points':
    title='恢复点';html=(route.points||[]).map(key=>btn('rollback',new Date(Number(key.replace('restore-',''))).toLocaleString('zh-CN'),`data-id="${key}"`,'list-row')).join('')||empty('恢复备份前会自动创建恢复点。');break;
  case 'trash':
    title='内容回收站';html=['message','post','diary','memory','event'].flatMap(type=>{const rows=type==='message'?scope.chats.flatMap(c=>c.messages):scope[{post:'posts',diary:'diaries',memory:'memories',event:'events'}[type]];return rows.filter(r=>r.deleted).map(r=>`<div class="card"><p>${esc((r.text||r.title||'').slice(0,120))}</p>${btn('restore-record','恢复',`data-id="${r.id}" data-kind="${type}"`)}</div>`);}).join('')||empty('没有被移除的内容。');break;
  case 'tasks':
    title='生成记录';html=tasksHTML(scope)+scope.tasks.filter(t=>t.status==='done').slice(-20).reverse().map(t=>`<div class="card"><strong>${esc(t.authorName||'角色')} · 已保存</strong>${meta(t.trace?.model||'')}${meta(`使用背景：${t.trace?.backgroundUsed?'是':'否'} · 使用回忆：${t.trace?.memoryIds?.length||0} 条`)}${meta(dateTime(t.at))}</div>`).join('');break;
  case 'confirm':title=route.title;html=`<p class="hint">${esc(route.message)}</p><div class="sheet-actions">${btn('cancel','取消','','secondary')}${btn(route.action,route.label||'确认',route.extra||'','primary')}</div>`;break;
  default:title='小手机';html=empty('从桌面打开一个应用吧。');
  }
  return {...common,title,html};
}
